from phoenix.keymap import KeyMap, Key


my_first_keymap = KeyMap(name="my first keymap")
my_second_keymap = KeyMap(name="my second keymap")

my_second_keymap.entry("lorem")
my_second_keymap.entry("ipsum")
my_second_keymap.entry("dolor")
my_second_keymap.entry("sit")
my_second_keymap.entry("amet")

my_first_keymap.link("hello", my_second_keymap)
my_first_keymap.link("world", my_second_keymap)

print("\nlength of new keymaps")
print(
    "first (=2x second):",
    len(my_first_keymap),
    "   second:",
    len(my_second_keymap),
)

print("\ncontent of keymaps")
for key, entry in my_first_keymap.items(recursive=True):
    print(f"\t{key}: {entry}")

print("\nkey composition")
print(
    Key("hello"),
    Key("lorem"),
    Key("hello", "lorem"),
    Key("hello", Key("lorem")),
    Key("hello") | Key("world"),
)

print("\naccess via get_item")
print('my_first_keymap["hello"]:', my_first_keymap["hello"])
print('my_first_keymap[Key("hello")]:', my_first_keymap[Key("hello")])
print(
    "composed access to hello | lorem:",
    my_first_keymap[Key("hello") | Key("lorem")],
    my_first_keymap[Key("hello", "lorem")],
)
print("we won't allow my_first_keymap['hello', 'lorem'] to work,")
print("to distinguish the composed key hello|lorem from the single")
print("tuple key (hello, lorem).")

print("\nwe can tag keys, too")
try:
    tagged_key = my_second_keymap.key("hello")
    lookup = my_first_keymap[tagged_key]
except KeyError as exc:
    print("something went wrong (as it should)")
    print("KeyError:", exc)
    print(
        "-> tagged key recognize their parent keymap and won't work on others"
    )
print("\nA therefore very safe way to access an entry:")
tagged_key = my_first_keymap.key("hello") | my_second_keymap.key("lorem")
print(my_first_keymap[tagged_key])

print(
    "even if the keys exist in another keymap, it won't work as the tags don't match"
)
copy_of_my_first_keymap = KeyMap(name="my first keymap again")
copy_of_my_first_keymap.link("hello", my_second_keymap)
copy_of_my_first_keymap.link("world", my_second_keymap)

try:
    fail_access = copy_of_my_first_keymap[tagged_key]
except KeyError as exc:
    print("KeyError:", exc)
print()

print("\nlet us use the tree method to visualize the keymap structure")
for level, key, entry in my_first_keymap.tree():
    print(" |" * level, entry)

print(
    "\nthe keymap also manages the assignment of keys to indices and vice versa"
)
# let us convert keys to offsets and vice versa
print(
    'my_first_keymap.key2off("world", "ipsum")',
    " -> ",
    my_first_keymap.key2off("world", "ipsum"),
)
print(
    "my_first_keymap.off2key(6)",
    " -> ",
    my_first_keymap.off2key(6),
)

# we can request the domain (entry, keymap, ...) at an index or key
print(
    'my_first_keymap.key2dom("world", "ipsum")',
    " -> ",
    my_first_keymap.key2dom("world", "ipsum"),
)
print(
    "my_first_keymap.off2dom(6)",
    " -> ",
    my_first_keymap.off2dom(6),
)

# when we access keymaps via keys, we need to distinguish
# a keymap you can find at an offset and the keymaps first entry
# that you can find at the same offset
print(
    'my_first_keymap.key2off("world")',
    " -> ",
    my_first_keymap.key2off("world"),
)
print(
    'my_first_keymap.key2off("world", "lorem")',
    " -> ",
    my_first_keymap.key2off("world", "lorem"),
)
print(
    'my_first_keymap.key2dom("world")',
    " -> ",
    my_first_keymap.key2dom("world"),
)
print(
    'my_first_keymap.key2dom("world", "lorem")',
    " -> ",
    my_first_keymap.key2dom("world", "lorem"),
)
print(
    "my_first_keymap.off2dom(5)",
    " -> ",
    my_first_keymap.off2dom(5),
)
